      "arFull": "بَرَآءَةٌ مِّنَ اللّٰهِ وَرَسُوْلِهٖۤ اِلَی الَّذِیْنَ عٰهَدْتُّمْ مِّنَ الْمُشْرِكِیْنَ ۟ؕ",
