      "number": 4,
      "arFull": "اِلَّا الَّذِیْنَ عٰهَدْتُّمْ مِّنَ الْمُشْرِكِیْنَ ثُمَّ لَمْ یَنْقُصُوْكُمْ شَیْـًٔا وَّلَمْ یُظَاهِرُوْا عَلَیْكُمْ اَحَدًا فَاَتِمُّوْۤا اِلَیْهِمْ عَهْدَهُمْ اِلٰی مُدَّتِهِمْ ؕ اِنَّ اللّٰهَ یُحِبُّ الْمُتَّقِیْنَ ۟",
      "ur": "بجز ان مشرکوں کے جن سے تمہارا معاہده ہو چکا ہے اور انہوں نے تمہیں ذرا سا بھی نقصان نہیں پہنچایا نہ کسی کی تمہارے خلاف مدد کی ہے تو تم بھی ان کے معاہدے کی مدت ان کے ساتھ پوری کرو[1] ، اللہ تعالیٰ پرہیزگاروں کو دوست رکھتا ہے۔",
