      "arFull": "كَیْفَ وَاِنْ یَّظْهَرُوْا عَلَیْكُمْ لَا یَرْقُبُوْا فِیْكُمْ اِلًّا وَّلَا ذِمَّةً ؕ یُرْضُوْنَكُمْ بِاَفْوَاهِهِمْ وَتَاْبٰی قُلُوْبُهُمْ ۚ وَاَكْثَرُهُمْ فٰسِقُوْنَ ۟ۚ",
