      "en": "How [can there be a treaty] while, if they gain dominance over you, they do not observe concerning you any pact of kinship or covenant of protection? They satisfy you with their mouths, but their hearts refuse [compliance], and most of them are defiantly disobedient.",
      "footnotesUr": "[1] كَيْفَ، پھر بطور تاکید، نفی کے لئے ہے۔ الَّ کے معنی قرابت (رشتہ داری) اور ذِمَّہ کے معنی عہد کے ہیں۔ یعنی ان مشرکین کی زبانی باتوں کا کیا اعتبار، جب کہ ان کا یہ حال ہے کہ اگر تم پر غالب آجائیں تو کسی قرابت اور عہد کا پاس نہیں کریں گے۔ بعض مفسرین کے نزدیک پہلا کیف مشرکین کے لئے ہے اور دوسرے سے یہودی مراد ہیں، کیونکہ ان کی صفت بیان کی گئی ہے کہ اللہ کی آیتوں کو کم قیمت پر بیچ دیتے ہیں۔ اور یہ وطیرہ یہودیوں کا ہی رہا ہے۔",
