      "arFull": "فَاِنْ تَابُوْا وَاَقَامُوا الصَّلٰوةَ وَاٰتَوُا الزَّكٰوةَ فَاِخْوَانُكُمْ فِی الدِّیْنِ ؕ وَنُفَصِّلُ الْاٰیٰتِ لِقَوْمٍ یَّعْلَمُوْنَ ۟",
      "ur": "اب بھی اگر یہ توبہ کر لیں اور نماز کے پابند ہو جائیں اور زکوٰة دیتے رہیں تو تمہارے دینی بھائی ہیں[1] ۔ ہم تو جاننے والوں کے لئے اپنی آیتیں کھول کھول کر بیان کر رہے ہیں۔",
      "en": "But if they repent, establish prayer, and give zakāh, then they are your brothers in religion; and We detail the verses for a people who know.",
      "footnotesUr": "[1] نماز، توحید و رسالت کے اقرار کے بعد، اسلام کا سب سے اہم رکن ہے جو اللہ کا حق ہے، اس میں اللہ کی عبادت کے مختلف پہلو ہیں۔ اس میں دست بستہ قیام ہے، رکوع و سجود ہے، دعا و مناجات ہے، اللہ کی عظمت و جلالت کا اور اپنی عاجزی و بے کسی کا اظہار ہے۔ عبادت کی یہ ساری صورتیں اور قسمیں صرف اللہ کے لئے خاص ہیں، نماز کے بعد دوسرا اہم فریضہ زکٰوۃ ہے، جس میں عبادتی پہلو کے ساتھ ساتھ خقوق العباد بھی شامل ہیں، زکٰو ۃ سے معاشرے کے اور زکٰوہ دینے والے کے قبیلے کے ضرورت مند، مفلس نادار اور معذور و محتاج لوگ فائدہ اٹھاتے ہیں، اسی لئے حدیث میں بھی شہادت کے بعد ان ہی دو چیزوں کو نمایاں کر کے بیان کیا گیا ہے۔ نبی کریم (صلى الله عليه وسلم) نے فرمایا: ”مجھے حکم دیا گیا ہے کہ میں لوگوں سے جنگ کروں، یہاں تک کہ وہ اس بات کی گواہی دیں کہ اللہ کے سوا کوئی معبود برحق نہیں اور محمد (صلى الله عليه وسلم) اللہ کے رسول ہیں، اور نماز قائم کریں اور زکٰو ۃ دیں“۔ (صحيح بخاري كتاب الإيمان باب فإن تابوا وأقاموا الصلاة مسلم، كتاب الإيمان، باب الأمر بقتال الناس)۔ حضرت عبد اللہ بن مسعود (رضي الله عنه) کا قول ہے: «مَنْ لَمْ يُزَكِّ، فَلَا صَلَاةَ لَهُ» (حوالہ مذکورہ) ”جس نے زکوۃ نہیں دی اس کی نماز بھی نہیں“۔",
