      "arFull": "یُبَشِّرُهُمْ رَبُّهُمْ بِرَحْمَةٍ مِّنْهُ وَرِضْوَانٍ وَّجَنّٰتٍ لَّهُمْ فِیْهَا نَعِیْمٌ مُّقِیْمٌ ۟ۙ",
