      "arFull": "لَقَدْ نَصَرَكُمُ اللّٰهُ فِیْ مَوَاطِنَ كَثِیْرَةٍ ۙ وَّیَوْمَ حُنَیْنٍ ۙ اِذْ اَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنْكُمْ شَیْـًٔا وَّضَاقَتْ عَلَیْكُمُ الْاَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّیْتُمْ مُّدْبِرِیْنَ ۟ۚ",
      "ur": "یقیناً اللہ تعالیٰ نے بہت سے میدانوں میں تمہیں فتح دی ہے اور حنین کی لڑائی والے دن بھی جب کہ تمہیں اپنی کثرت پر ناز ہوگیا تھا، لیکن اس نے تمہیں کوئی فائده نہ دیا بلکہ زمین باوجود اپنی کشادگی کے تم پر تنگ ہوگئی پھر تم پیٹھ پھیر کر مڑ گئے۔",
