      "arFull": "وَمِنْهُمْ مَّنْ یَّلْمِزُكَ فِی الصَّدَقٰتِ ۚ فَاِنْ اُعْطُوْا مِنْهَا رَضُوْا وَاِنْ لَّمْ یُعْطَوْا مِنْهَاۤ اِذَا هُمْ یَسْخَطُوْنَ ۟",
      "ur": "ان میں وه بھی ہیں جو خیراتی مال کی تقسیم کے بارے میں آپ پر عیب رکھتے ہیں[1] ، اگر انہیں اس میں سے مل جائے تو خوش ہیں اور اگر اس میں سے نہ ملا تو فوراً بگڑ کھڑے ہوئے۔[2]",
      "en": "And among them are some who criticize you concerning the [distribution of] charities. If they are given from them, they approve; but if they are not given from them, at once they become angry.",
      "footnotesUr": "[1] یہ ان کی ایک اور بہت بڑی کوتاہی کا بیان ہے کہ وہ نبی (صلى الله عليه وسلم) کی ذات ستودہ صفات کو (نعوذ باللہ) صدقات و غنائم کی تقسیم میں غیر منصف باور کراتے، جس طرح ابن ذی الخویصرہ کے بارے میں آتا ہے کہ آپ (صلى الله عليه وسلم) ایک مرتبہ تقسیم فرما رہے تھے کہ اس نے کہا \"انصاف سے کام لیجئے\" آپ (صلى الله عليه وسلم) نے فرمایا: ”افسوس ہے تجھ پر، اگر میں ہی انصاف نہیں کروں گا تو پھر کون کرے گا؟“۔ (صحيح بخاري- كتاب المناقب، باب علامات النبوة صحيح مسلم- كتاب الزكاة باب ذكر الخوارج ...)۔\n[2] گویا اس الزام تراشی کا مقصد محض مالی مفادات کا حصول تھا کہ اس طرح ان سے ڈرتے ہوئے انہیں زیادہ حصہ دیا جائے، یا وہ مستحق ہوں یا نہ ہوں، انہیں حصہ ضرور دیا جائے۔",
