      "number": 61,
      "arFull": "وَمِنْهُمُ الَّذِیْنَ یُؤْذُوْنَ النَّبِیَّ وَیَقُوْلُوْنَ هُوَ اُذُنٌ ؕ قُلْ اُذُنُ خَیْرٍ لَّكُمْ یُؤْمِنُ بِاللّٰهِ وَیُؤْمِنُ لِلْمُؤْمِنِیْنَ وَرَحْمَةٌ لِّلَّذِیْنَ اٰمَنُوْا مِنْكُمْ ؕ وَالَّذِیْنَ یُؤْذُوْنَ رَسُوْلَ اللّٰهِ لَهُمْ عَذَابٌ اَلِیْمٌ ۟",
      "ur": "ان میں سے وه بھی ہیں جو پیغمبر کو ایذا دیتے ہیں اور کہتے ہیں کان کا کچا ہے، آپ کہہ دیجئے کہ وه کان تمہارے بھلے کے لئے ہے[1] وه اللہ پر ایمان رکھتا ہے اور مسلمانوں کی بات کا یقین کرتا ہے اور تم میں سے جو اہل ایمان ہیں یہ ان کے لئے رحمت ہے، رسول اللہ ﴿صلی اللہ علیہ وسلم﴾ کو جو لوگ ایذا دیتے ہیں ان کے لئے دکھ کی مار ہے۔",
      "en": "And among them are those who abuse the Prophet and say, \"He is an ear.\"[488] Say, \"[It is] an ear of goodness for you that believes in Allāh and believes the believers and [is] a mercy to those who believe among you.\" And those who abuse the Messenger of Allāh - for them is a painful punishment.",
      "footnotesUr": "[1] یہاں سے پھر منافقین کا ذکر ہو رہا ہے نبی (صلى الله عليه وسلم) کے خلاف ایک ہرزہ سرائی انہوں نے یہ کی کہ یہ کان کا کچا (ہلکا) ہے، مطلب ہے کہ یہ ہر ایک بات سن لیتا ہے (یہ گویا آپ صلى الله عليه وسلم کے حلم و کرم اور عفو و صفع کی صفت سے ان کو دھوکہ ہوا) اللہ نے فرمایا کہ نہیں، ہمارا پیغمبر شر و فساد کی کوئی بات نہیں سنتا جو بھی سنتا ہے تمہارے لئے اس میں خیر اور بھلائی ہے۔",
      "footnotesEn": "[488] i.e., one who believes everything he hears.",
