      "number": 71,
      "arFull": "وَالْمُؤْمِنُوْنَ وَالْمُؤْمِنٰتُ بَعْضُهُمْ اَوْلِیَآءُ بَعْضٍ ۘ یَاْمُرُوْنَ بِالْمَعْرُوْفِ وَیَنْهَوْنَ عَنِ الْمُنْكَرِ وَیُقِیْمُوْنَ الصَّلٰوةَ وَیُؤْتُوْنَ الزَّكٰوةَ وَیُطِیْعُوْنَ اللّٰهَ وَرَسُوْلَهٗ ؕ اُولٰٓىِٕكَ سَیَرْحَمُهُمُ اللّٰهُ ؕ اِنَّ اللّٰهَ عَزِیْزٌ حَكِیْمٌ ۟",
      "ur": "مومن مرد وعورت آپس میں ایک دوسرے کے (مددگار ومعاون اور) دوست ہیں[1] ، وه بھلائیوں کا حکم دیتے ہیں اور برائیوں سے روکتے ہیں[2]، نمازوں کو پابندی سے بجا ﻻتے ہیں زکوٰة ادا کرتے ہیں، اللہ کی اور اس کے رسول کی بات مانتے ہیں[3]، یہی لوگ ہیں جن پر اللہ تعالیٰ بہت جلد رحم فرمائے گا بیشک اللہ غلبے واﻻ حکمت واﻻ ہے۔",
      "en": "The believing men and believing women are allies of one another. They enjoin what is right and forbid what is wrong and establish prayer and give zakāh and obey Allāh and His Messenger. Those - Allāh will have mercy upon them. Indeed, Allāh is Exalted in Might and Wise.",
      "footnotesUr": "[1] منافقین کی صفات مذمومہ کے مقابلے مومنین کی صفات محمودہ کا ذکر ہو رہا ہے پہلی صفت وہ ایک دوسرے کے دوست، معاون و غم خوار ہیں جس طرح حدیث میں ہے: «الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا»( صحيح بخاري- كتاب الصلاة ، باب تشبيك الأصابع في المسجد وغيره- مسلم، باب تراحم المؤمنين وتعاطفهم وتعاضدهم) ”مومن مومن کے لیے ایک دیوار کی طرح ہے جس کی ایک اینٹ دوسری اینٹ کی مضبوطی کا ذریعہ ہے“۔ دوسری حدیث میں فرمایا:«مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ، كَمَثَلِ الْجَسَدِ الْوَاحِدِ إِذَا اشْتَكَى مِنْه عُضْوٌ ، تَدَاعَى لَه سَائِرُ الْجَسَدِ بِالْحُمّى وَالسَّهَرِ»، ( صحيح مسلم، باب مذكور، والبخاري - كتاب الأدب، باب رحمة الناس والبهائم) ”مومنوں کی مثال، آپس میں ایک دوسرے کے ساتھ محبت کرنے اور رحم کرنے میں ایک جسم کی طرح ہے جب جسم کے ایک عضو کو تکلیف ہوتی ہے تو سارا جسم تپ کا شکار ہو جاتا ہے اور بیدار رہتا ہے“۔\n[2] یہ اہل ایمان کی دوسری خاص صفت ہے معروف وہ ہے جسے شریعت نے معروف (یعنی نیکی اور بھلائی) اور منکر وہ ہے جسے شریعت نے منکر (یعنی برا) قرار دیا ہے۔ نہ کہ وہ جسے لوگ اچھا یا برا کہیں۔\n[3] نماز، حقوق اللہ میں نمایاں ترین عبادت ہے اور زکٰوۃ حقوق العباد کے لحاظ سے، امتیازی حیثیت رکھتی ہے۔ اس لئے ان دونوں کا بطور خاص تذکرہ کر کے فرما دیا گیا کہ وہ ہر معاملے میں اللہ اور رسول کی اطاعت کرتے ہیں۔",
      "footnotesEn": null,
