      "number": 82,
      "arFull": "فَلْیَضْحَكُوْا قَلِیْلًا وَّلْیَبْكُوْا كَثِیْرًا ۚ جَزَآءً بِمَا كَانُوْا یَكْسِبُوْنَ ۟",
      "ur": "پس انہیں چاہئے کہ بہت کم ہنسیں اور بہت زیاده روئیں[1] بدلے میں اس کے جو یہ کرتے تھے۔",
      "en": "So let them laugh a little and [then] weep much as recompense for what they used to earn.",
