      "arFull": "وَلَا تُعْجِبْكَ اَمْوَالُهُمْ وَاَوْلَادُهُمْ ؕ اِنَّمَا یُرِیْدُ اللّٰهُ اَنْ یُّعَذِّبَهُمْ بِهَا فِی الدُّنْیَا وَتَزْهَقَ اَنْفُسُهُمْ وَهُمْ كٰفِرُوْنَ ۟",
