      "ur": "اور ان دیہاتیوں میں سے بعض[1] ایسے ہیں کہ جو کچھ خرچ کرتے ہیں اس کو جرمانہ سمجھتے ہیں[2] اور تم مسلمانوں کے واسطے برے وقت کے منتظر رہتے ہیں[3]، برا وقت ان ہی پر پڑنے واﻻ ہے[4] اور اللہ سننے واﻻ جاننے واﻻ ہے۔",
      "en": "And among the bedouins are some who consider what they spend as a loss[499] and await for you turns of misfortune. Upon them will be a misfortune of evil. And Allāh is Hearing and Knowing.",
      "footnotesUr": "[1] اب ان دیہاتیوں کی دو قسمیں بیان کی جا رہی ہیں یہ پہلی قسم ہے۔\n[2] غُرْم تاوان اور جرمانے کو کہتے ہیں۔ یعنی ایسا خرچ ہو جو انسان کو نہایت ناگواری سے ناچار کرنا پڑ جاتا ہے۔\n[3] دَوَائِرُ۔ دَا ئِرَۃ کی جمع ہے، گردش زمانہ یعنی مصائب و آلام یعنی وہ منتظر رہتے ہیں کہ مسلمان زمانے کی گردشوں یعنی مصائب کا شکار ہوں۔\n[4] یہ بد دعا یا خبر ہے کہ زمانے کی گردش ان پر ہی پڑے۔ کیونکہ وہی اس کے مستحق ہیں۔",
