      "number": 101,
      "arFull": "وَمِمَّنْ حَوْلَكُمْ مِّنَ الْاَعْرَابِ مُنٰفِقُوْنَ ۛؕ وَمِنْ اَهْلِ الْمَدِیْنَةِ ؔۛ۫ مَرَدُوْا عَلَی النِّفَاقِ ۫ لَا تَعْلَمُهُمْ ؕ نَحْنُ نَعْلَمُهُمْ ؕ سَنُعَذِّبُهُمْ مَّرَّتَیْنِ ثُمَّ یُرَدُّوْنَ اِلٰی عَذَابٍ عَظِیْمٍ ۟ۚ",
      "ur": "اور کچھ تمہارے گردوپیش والوں میں اور کچھ مدینے والوں میں ایسے منافق ہیں کہ نفاق پر اڑے[1] ہوئے ہیں، آپ ان کو نہیں جانتے[2]، ان کو ہم جانتے ہیں ہم ان کو دہری سزا دیں گے[3]، پھر وه بڑے بھاری عذاب کی طرف بھیجے جائیں گے۔",
      "en": "And among those around you of the bedouins are hypocrites, and [also] from the people of Madīnah. They have persisted in hypocrisy. You, [O Muḥammad], do not know them, [but] We know them. We will punish them twice [in this world]; then they will be returned to a great punishment.",
      "footnotesUr": "[1] مَرَدَ اور تَمَرَّدَ کے معنی ہیں نرمی ملائمت (چکناہٹ) اور تجرد۔ چنانچہ اس شاخ کو جو بغیر پتے کے ہو، وہ گھوڑا جو بغیر بال کے ہو، وہ لڑکا جس کے چہرے پر بال نہ ہوں، ان سب کو اَمْرَدُ کہا جاتا ہے اور شیشے کو صَرْح مُمَرَّد اَیْ مُجَرَّدً کہا جاتا ہے۔ ”مَرَدُوْا عَلَی النِّفَاقِ“ کے معنی ہوں گے تَجَرَّدُوا عَلیَ النِّفَاقِ، گویا انہوں نے نفاق کے لئے اپنے آپ کو خالص اور تنہا کر لیا، یعنی اس پر ان کا اصرار اور استمرار ہے۔\n[2] کتنے واضح الفاظ میں نبی (صلى الله عليه وسلم) سے علم غیب کی نفی ہے۔ کاش اہل بدعت کو قرآن سمجھنے کی توفیق نصیب ہو۔\n[3] اس سے مراد بعض کے نزدیک دنیا کی ذلت و رسوائی اور پھر آخرت کا عذاب ہے اور بعض کے نزدیک دنیا میں ہی دوہری سزا ہے۔",
