      "arFull": "وَلَا یُنْفِقُوْنَ نَفَقَةً صَغِیْرَةً وَّلَا كَبِیْرَةً وَّلَا یَقْطَعُوْنَ وَادِیًا اِلَّا كُتِبَ لَهُمْ لِیَجْزِیَهُمُ اللّٰهُ اَحْسَنَ مَا كَانُوْا یَعْمَلُوْنَ ۟",
      "ur": "اور جو کچھ چھوٹا بڑا انہوں نے خرچ کیا اور جتنے میدان ان کو طے کرنے پڑے[1] ، یہ سب بھی ان کے نام لکھا گیا تاکہ اللہ تعالیٰ ان کے کاموں کا اچھے سے اچھا بدلہ دے۔",
      "en": "Nor do they spend an expenditure, small or large, or cross a valley but that it is registered for them that Allāh may reward them for the best of what they were doing.",
      "footnotesUr": "[1] پہاڑوں کے میدان اور پانی کی گزرگاہ کو وادی کہتے ہیں۔ مراد یہاں مطلق وادیاں اور علاقے ہیں۔ یعنی اللہ کی راہ میں تھوڑا یا زیادہ جتنا بھی خرچ کرو گے اسی طرح جتنے بھی میدان طے کرو گے، (یعنی جہاد میں تھوڑا یا زیادہ سفر کرو گے) یہ سب نیکیاں تمہارے نامہ اعمال میں درج ہونگی جن پر اللہ تعالٰی اچھا سے اچھا بدلہ عطا فرمائے گا۔",
